// Safe SSH exec helper for server cmsc9l72y000ghl7iyd87u5ja (Soul Pilates .200).
// Decrypts rootPasswordEnc in memory via lib/crypto-box; NEVER prints the password.
// Usage: node ssh-exec.mjs '<remote command>'   (command read from argv[2] or stdin)
import { config } from "dotenv";
import { PrismaClient } from "@prisma/client";
import { Client } from "ssh2";
import { decryptSecret } from "/opt/nxeon/lib/crypto-box.ts";

config({ path: "/opt/nxeon/.env" });

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
const EXPECT_IP = "51.79.226.200";

async function main() {
  let cmd = process.argv[2];
  if (!cmd) {
    cmd = await new Promise((r) => {
      let d = "";
      process.stdin.on("data", (c) => (d += c));
      process.stdin.on("end", () => r(d));
    });
  }
  const prisma = new PrismaClient();
  const server = await prisma.server.findUnique({
    where: { id: SERVER_ID },
    include: { dedicatedIp: true },
  });
  await prisma.$disconnect();
  if (!server) throw new Error("server row not found");

  const dedicated = !!server.dedicatedIp;
  const host = dedicated ? server.dedicatedIp.address : process.env.PUBLIC_IP;
  const port = dedicated ? 22 : server.sshPort;
  const password = decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
  if (!password) throw new Error("no root password");

  // Safety: prepend an assertion that the box really is .200.
  const guarded =
    `if ! hostname -I | grep -qw ${EXPECT_IP}; then echo "ABORT: not ${EXPECT_IP}"; exit 99; fi\n` +
    cmd;

  const conn = new Client();
  const code = await new Promise((resolve, reject) => {
    conn.on("ready", () => {
      conn.exec(guarded, { pty: false }, (err, stream) => {
        if (err) return reject(err);
        stream.on("close", (c) => {
          conn.end();
          resolve(c);
        });
        stream.on("data", (d) => process.stdout.write(d));
        stream.stderr.on("data", (d) => process.stderr.write(d));
      });
    });
    conn.on("error", reject);
    conn.connect({ host, port, username: "root", password, readyTimeout: 20000 });
  });
  process.exit(code ?? 0);
}
